function abilityOnFire(tw,T,tgt,R,proj){const v=AV(tw);if(!v)return;const type=AB(tw).type;if(type==='multishot'){const others=G.enemies.filter(e=>e!==tgt&&e.hp>0&&inRange(tw,e,R)).sort((a,b)=>(a.path.len-a.dist)-(b.path.len-b.dist)).slice(0,v);for(const e of others){const q=enemyPos(e);G.projs.push({...proj,tgt:e,tx:q.x,ty:q.y,dmg:proj.dmg*0.7});}}else if(type==='heavy'){tw.shots=(tw.shots||0)+1;if(tw.shots%v.n===0){proj.dmg*=v.m;proj.splash*=1.4;proj.heavy=true;proj.arc*=1.2;}}}
